using System.Runtime.InteropServices;
using System.Text.Json;
using Microsoft.Win32.SafeHandles;
using SoopaDriveTool.Core;
namespace SoopaDriveTool.Windows;
public record VolumeExtent(string Volume,string Letter,long Offset,long Length,int Disk,bool Simple);
public static class DynamicDiskService
{
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr FindFirstVolume(System.Text.StringBuilder name,int size);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool FindNextVolume(IntPtr search,System.Text.StringBuilder name,int size);
    [DllImport("kernel32.dll")]static extern bool FindVolumeClose(IntPtr search);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool GetVolumePathNamesForVolumeName(string volume,char[] paths,int count,out int required);
    static SafeFileHandle Open(string path,bool write=false){var h=CreateFile(path,write?0xc0000000u:0x80000000u,3,IntPtr.Zero,3,0,IntPtr.Zero);if(h.IsInvalid){h.Dispose();throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}return h;}
    public static List<VolumeExtent> Extents(int selected)
    {
        var rows=new List<VolumeExtent>();var buffer=new System.Text.StringBuilder(1024);IntPtr search=FindFirstVolume(buffer,buffer.Capacity);if(search==new IntPtr(-1))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
        try{do{string volume=buffer.ToString();try{using var h=Open(volume.TrimEnd('\\'));byte[] data=new byte[65536];if(!DiskAccess.DeviceIoControl(h,0x560000,null,0,data,data.Length,out int got,IntPtr.Zero))continue;int count=BitConverter.ToInt32(data);if(count<1||count>1024||got<8+24*count)throw new IOException("Invalid volume extent map.");char[] paths=new char[32768];string letter="";if(GetVolumePathNamesForVolumeName(volume,paths,paths.Length,out _))letter=new string(paths).Split('\0').FirstOrDefault(p=>p.Length==3&&p[1]==':')?[..1]??"";for(int i=0;i<count;i++){int number=BitConverter.ToInt32(data,8+i*24);if(number==selected)rows.Add(new(volume,letter,BitConverter.ToInt64(data,16+i*24),BitConverter.ToInt64(data,24+i*24),number,count==1));}}catch(System.ComponentModel.Win32Exception){}}while(FindNextVolume(search,buffer,buffer.Capacity));}finally{FindVolumeClose(search);}return rows.OrderBy(r=>r.Offset).ToList();
    }
    public static DiskInfo Inspect(DiskInfo seed)
    {
        using var h=Open(@"\\.\PhysicalDrive"+seed.Number);byte[] geometry=new byte[256],length=new byte[8],attributes=new byte[16];if(!DiskAccess.DeviceIoControl(h,0x700a0,null,0,geometry,geometry.Length,out _,IntPtr.Zero)||!DiskAccess.DeviceIoControl(h,0x7405c,null,0,length,8,out _,IntPtr.Zero))throw new IOException("Dynamic disk geometry is unavailable.");int sector=BitConverter.ToInt32(geometry,20);ulong flags=DiskAccess.DeviceIoControl(h,0x700f0,null,0,attributes,16,out _,IntPtr.Zero)?BitConverter.ToUInt64(attributes,8):0;
        long bytes=BitConverter.ToInt64(length);DiskTable? table=null;using(var stream=new DiskAccess.BoundDiskStream(new FileStream(h,FileAccess.Read,1,false),bytes,h,sector)){try{table=DiskTables.Read(stream,sector);}catch(IOException){}}
        bool dynamic=table?.Style=="MBR"?table.Partitions.Any(p=>p.MbrType==0x42):table?.Partitions.Any(p=>p.Type==Guid.Parse("af9b60a0-1431-4f62-bc68-3311714a69ad")||p.Type==Guid.Parse("5808c8aa-7e8f-42e0-85d2-e1e90434cfb3"))==true;
        var extents=Extents(seed.Number);var parts=extents.Select((e,i)=>{string fs="",label="";long free=0;if(e.Letter.Length==1){var drive=new DriveInfo(e.Letter+@":\");if(drive.IsReady){fs=drive.DriveFormat;label=drive.VolumeLabel;free=drive.AvailableFreeSpace;}}return new PartitionInfo{Number=i+1,Offset=e.Offset,Size=e.Length,Letter=e.Letter,Label=label,FileSystem=fs,Free=free,Type=e.Simple?"Dynamic simple":"Dynamic multi-disk",Encryption="Unknown",IsBoot=e.Letter.Equals(Path.GetPathRoot(Environment.SystemDirectory)![..1],StringComparison.OrdinalIgnoreCase)};}).ToList();
        return seed with{Style=dynamic?"Dynamic":"Unavailable",Size=bytes,SectorSize=sector,Offline=(flags&1)!=0,ReadOnly=(flags&2)!=0,NativeIdentity=DiskAccess.Fingerprint(seed.Number),Partitions=parts,IsBoot=parts.Any(p=>p.IsBoot),IsSystem=parts.Any(p=>p.IsBoot)||table?.Partitions.Any(p=>p.Type==DiskTables.Efi)==true};
    }
    public static async Task<string> ConvertAsync(DiskOperation operation,DiskInfo disk,IProgress<DriveProgress>? progress)
    {
        if(!StorageService.IsAdmin||disk.Protected||disk.ReadOnly||disk.Offline)throw new IOException("Choose an online, writable inactive data disk.");await DiskAccess.RequireSeparatePathAsync(operation.Workspace,disk.Number);string folder=Path.Combine(operation.Workspace,"SoopaDynamic-"+operation.Id.ToString("N"));Directory.CreateDirectory(folder);
        if(operation.Value=="Dynamic")
        {
            if(disk.Style is not ("GPT" or "MBR")||disk.Partitions.Any(p=>p.Protected&&!p.Type.Contains("Reserved",StringComparison.OrdinalIgnoreCase)||p.Encryption!="None"))throw new IOException("Basic-to-dynamic conversion requires an ordinary unencrypted data disk without boot or recovery partitions.");await Data.SaveAsync(Path.Combine(folder,"original-basic.json"),disk);using(var original=DiskAccess.Open(disk,false,false)){await File.WriteAllBytesAsync(Path.Combine(folder,"original-first-MiB.bin"),DiskTables.ReadAt(original,0,1024*1024));await File.WriteAllBytesAsync(Path.Combine(folder,"original-last-MiB.bin"),DiskTables.ReadAt(original,original.Length-1024*1024,1024*1024));}string script=Path.Combine(folder,"convert.txt");await File.WriteAllTextAsync(script,$"select disk {disk.Number}\nconvert dynamic\nexit\n");var r=await ProcessTool.RunAsync(Path.Combine(Environment.SystemDirectory,"diskpart.exe"),["/s",script]);await File.WriteAllTextAsync(Path.Combine(folder,"diskpart.log"),r.Output+r.Error);var after=(await StorageService.InventoryAsync()).SingleOrDefault(d=>d.Number==disk.Number);if(r.ExitCode!=0||(after?.Style!="Dynamic"||after.NativeIdentity!=disk.NativeIdentity))throw new IOException("Windows did not convert this device to dynamic storage. Read the saved DiskPart log; some Windows editions, removable drives and virtual disks do not support dynamic disks.");return "Windows converted the data disk to dynamic storage. Original layout and provider log retained at "+folder;
        }
        if(operation.Value!="Basic"||disk.Style!="Dynamic")throw new IOException("Choose a dynamic disk for simple-volume conversion to basic.");var extents=Extents(disk.Number);if(extents.Count==0||extents.Any(e=>!e.Simple))throw new IOException("Lossless conversion requires single contiguous NTFS volumes. Spanned, striped, mirrored and RAID-5 volumes require migration to separate basic disks.");var locks=new List<SafeFileHandle>();
        try
        {
            foreach(var e in extents){var volume=Open(e.Volume.TrimEnd('\\'),true);try{if(!DiskAccess.DeviceIoControl(volume,0x90018,null,0,null,0,out _,IntPtr.Zero)||!DiskAccess.DeviceIoControl(volume,0x90020,null,0,null,0,out _,IntPtr.Zero))throw new IOException("Close applications using the dynamic volume before conversion.");locks.Add(volume);}catch{volume.Dispose();throw;}}
            using var raw=DiskAccess.Open(disk,true,false);var old=DiskTables.Read(raw,disk.SectorSize);if(old.Partitions.Any(p=>p.Type==DiskTables.Efi||p.Type==DiskTables.Recovery))throw new IOException("System/recovery layouts require a Windows migration.");var parts=new List<TablePartition>();foreach(var e in extents){var boot=DiskTables.ReadAt(raw,e.Offset,disk.SectorSize);if(System.Text.Encoding.ASCII.GetString(boot,3,8)!="NTFS    "||BitConverter.ToUInt16(boot,11)!=disk.SectorSize||BitConverter.ToUInt64(boot,40)>(ulong)(e.Length/disk.SectorSize))throw new IOException("A dynamic volume is not a bounded NTFS extent.");parts.Add(new(parts.Count+1,e.Offset,e.Length,DiskTables.Basic,Guid.NewGuid(),"Recovered simple volume"));}
            var next=new DiskTable("GPT",disk.SectorSize,disk.Size,old.Id==Guid.Empty?Guid.NewGuid():old.Id,old.Signature,parts);await Data.SaveAsync(Path.Combine(folder,"conversion.json"),new{Original=old,Replacement=next,Extents=extents});await File.WriteAllBytesAsync(Path.Combine(folder,"original-first-MiB.bin"),DiskTables.ReadAt(raw,0,1024*1024));await File.WriteAllBytesAsync(Path.Combine(folder,"original-last-MiB.bin"),DiskTables.ReadAt(raw,raw.Length-1024*1024,1024*1024));
            byte[] offline=new byte[40];BitConverter.GetBytes(40u).CopyTo(offline,0);offline[4]=1;BitConverter.GetBytes(1UL).CopyTo(offline,8);BitConverter.GetBytes(1UL).CopyTo(offline,16);if(!DiskAccess.DeviceIoControl(raw.Handle,0x7c0f4,offline,offline.Length,null,0,out _,IntPtr.Zero))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());DiskTables.Write(raw,next);raw.Flush();var verified=DiskTables.Read(raw,disk.SectorSize);if(verified.Partitions.Count!=parts.Count)throw new IOException("Basic table read-back failed; keep the original sector backup.");progress?.Report(new("Basic table verified",100,"The disk remains offline. Restart Windows before bringing the converted basic disk online."));return "Simple NTFS extents preserved and a basic GPT table verified. Disk kept offline; restart Windows to unload its dynamic-disk metadata before mounting it. Original sector backups: "+folder;
        }
        finally{foreach(var h in locks){DiskAccess.DeviceIoControl(h,0x9001c,null,0,null,0,out _,IntPtr.Zero);h.Dispose();}}
    }
}
